fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Extract the j-th column from the input matrix of size n x m
    // The column length is n, as there are n rows
    // For each row i, take input[i][j]
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Construct the transpose of input, which has n rows and m columns
    // The output will have m rows and n columns
    // Each output row j is the j-th column of input
    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }
    result
}